export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;
  const lagTau = 0.038;
  const lagAlpha = 1 - Math.exp(-dt / lagTau);

  let prevVel = null;
  let prevAtt = null;
  let prevRates = null;
  let lastAction = { thrust: 0.45, roll: 0, pitch: 0, yawRate: 0 };

  let thrustLag = 0.45;
  let thrustScale = 21.0;

  let simInt = { roll: 0, pitch: 0 };
  let alphaLag = { roll: 0, pitch: 0, yaw: 0 };
  let torqueBias = { roll: 0, pitch: 0, yaw: 0 };

  let windInst = { x: 0, z: 0 };
  let baseWind = { x: 0, z: 0 };
  let gustEst = { x: 0, z: 0 };
  let windInit = false;

  let prevRollDes = 0;
  let prevPitchDes = 0;

  let gateIdx = -1;
  let mode = 'align';
  let centeredCount = 0;
  let padPhase = 'approach';

  return {
    step(obs) {
      const p = obs.pos;
      const v = obs.vel;
      const att = obs.att;
      const rates = obs.rates;

      const cy = Math.cos(att.yaw);
      const sy = Math.sin(att.yaw);
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const dir = {
        x: cy * bodyX + sy * bodyZ,
        y: Math.cos(att.pitch) * Math.cos(att.roll),
        z: -sy * bodyX + cy * bodyZ,
      };

      if (prevRates !== null) {
        for (const axis of ['roll', 'pitch']) {
          const errPrev = lastAction[axis] - prevAtt[axis];
          simInt[axis] = clamp(simInt[axis] + errPrev * dt, -0.35, 0.35);
          const cmd = 65 * errPrev - 13.4 * prevRates[axis] + 22 * simInt[axis];
          alphaLag[axis] += lagAlpha * (cmd - alphaLag[axis]);
          const meas = (rates[axis] - prevRates[axis]) / dt;
          if (p.y > 0.085 && thrustLag > 0.15) {
            const res = meas - (alphaLag[axis] + torqueBias[axis] * thrustLag);
            torqueBias[axis] = clamp(torqueBias[axis] + 0.07 * res / Math.max(0.25, thrustLag), -32, 32);
          }
        }
        const yawCmd = 8 * (lastAction.yawRate - prevRates.yaw) - 0.4 * prevRates.yaw;
        alphaLag.yaw += lagAlpha * (yawCmd - alphaLag.yaw);
        const yawMeas = (rates.yaw - prevRates.yaw) / dt;
        if (p.y > 0.085 && thrustLag > 0.15) {
          const yawRes = yawMeas - (alphaLag.yaw + torqueBias.yaw * thrustLag);
          torqueBias.yaw = clamp(torqueBias.yaw + 0.07 * yawRes / Math.max(0.25, thrustLag), -10, 10);
        }
      }

      if (prevVel !== null && p.y > 0.095) {
        const massEst = clamp(15.3 / thrustScale, 0.6, 0.95);
        const dragCoeff = 0.42 / massEst;

        const ayMeas = (v.y - prevVel.y) / dt;
        const uy = thrustLag * dir.y;
        if (uy > 0.22) {
          const ayPred = thrustScale * uy - dragCoeff * prevVel.y - 9.81;
          const gainTs = obs.t < 1.5 ? 0.08 : 0.03;
          thrustScale = clamp(thrustScale + gainTs * (ayMeas - ayPred) / uy, 14.5, 27.5);
        }

        const massEst2 = clamp(15.3 / thrustScale, 0.6, 0.95);
        const drag2 = 0.42 / massEst2;
        const S = thrustScale * thrustLag;
        const wxRaw = (v.x - prevVel.x) / dt - S * dir.x + drag2 * v.x;
        const wzRaw = (v.z - prevVel.z) / dt - S * dir.z + drag2 * v.z;

        if (!windInit) {
          windInst.x = wxRaw;
          windInst.z = wzRaw;
          baseWind.x = wxRaw;
          baseWind.z = wzRaw;
          windInit = true;
        } else {
          windInst.x += 0.42 * (wxRaw - windInst.x);
          windInst.z += 0.42 * (wzRaw - windInst.z);
        }

        if (obs.t < 1.95) {
          const bwGain = obs.t < 0.4 ? 0.15 : 0.06;
          baseWind.x += bwGain * (windInst.x - baseWind.x);
          baseWind.z += bwGain * (windInst.z - baseWind.z);
          gustEst.x = 0;
          gustEst.z = 0;
        } else {
          const gx = windInst.x - baseWind.x;
          const gz = windInst.z - baseWind.z;
          const gMag = Math.hypot(gx, gz);
          if (gMag < 0.85) {
            baseWind.x += 0.015 * gx;
            baseWind.z += 0.015 * gz;
            gustEst.x *= 0.65;
            gustEst.z *= 0.65;
          } else {
            const gGain = gMag > 2.0 ? 0.42 : 0.28;
            gustEst.x += gGain * (gx - gustEst.x);
            gustEst.z += gGain * (gz - gustEst.z);
          }
        }
      }

      thrustLag += lagAlpha * (lastAction.thrust - thrustLag);
      prevVel = { x: v.x, y: v.y, z: v.z };
      prevAtt = { roll: att.roll, pitch: att.pitch, yaw: att.yaw };
      prevRates = { roll: rates.roll, pitch: rates.pitch, yaw: rates.yaw };

      const massEst = clamp(15.3 / thrustScale, 0.6, 0.95);
      const dragCoeff = 0.42 / massEst;
      const windAccX = baseWind.x + gustEst.x;
      const windAccZ = baseWind.z + gustEst.z;
      const gustMag = Math.hypot(gustEst.x, gustEst.z);
      const gustTransient = Math.hypot(windInst.x - (baseWind.x + gustEst.x), windInst.z - (baseWind.z + gustEst.z));

      let axDes = 0, ayDes = 0, azDes = 0;
      let maxTilt = 0.48;
      let pinPad = false;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          mode = 'align';
          centeredCount = 0;
        }

        const dx = g.x - p.x;
        const dy = g.y - p.y;
        const dz = g.z - p.z;
        const absDy = Math.abs(dy);
        const absDz = Math.abs(dz);

        const tPred = clamp(dx / Math.max(v.x, 0.4), 0.04, 0.22);
        const zPredErr = Math.abs((p.z + v.z * tPred) - g.z);
        const yPredErr = Math.abs((p.y + v.y * tPred) - g.y);

        if (mode === 'align') {
          const centered =
            dx > 0.08 && dx < 0.38 &&
            absDz < 0.017 && zPredErr < 0.020 && Math.abs(v.z) < 0.11 &&
            absDy < 0.065 && yPredErr < 0.075 && Math.abs(v.y) < 0.25 &&
            v.x > -0.15 &&
            gustTransient < 1.1 && gustMag < 3.2;

          if (centered) centeredCount++;
          else centeredCount = 0;

          if (centeredCount >= 3) {
            mode = 'lunge';
          }
        } else if (mode === 'lunge') {
          const stopDist = Math.max(0.065, (v.x * Math.max(0, v.x)) / (2 * 4.2) + 0.04);
          const unaligned = zPredErr > 0.027 || absDz > 0.025 || yPredErr > 0.105 || absDy > 0.095 || gustTransient > 1.8;
          if (dx > stopDist && unaligned) {
            mode = 'align';
            centeredCount = 0;
          }
        }

        if (mode === 'align') {
          const alignDist = (absDz > 0.035 || absDy > 0.11 || gustMag > 2.0) ? 0.32 : 0.26;
          const tx = g.x - alignDist;
          const kpx = 6.5;
          const kdx = gustMag > 1.5 ? 5.2 : 4.4;
          axDes = clamp(kpx * (tx - p.x) - kdx * v.x, -4.5, 4.5);
          if (dx < 0.22 && (absDz > 0.024 || absDy > 0.09)) {
            axDes = Math.min(axDes, -2.5 * v.x - 1.5);
          }

          const kpz = 11.5;
          const kdz = gustMag > 1.5 ? 6.8 : 6.0;
          azDes = clamp(kpz * (g.z - p.z) - kdz * v.z, -5.2, 5.2);

          const kpy = 11.0;
          const kdy = 5.6;
          ayDes = clamp(kpy * (g.y - p.y) - kdy * v.y, -4.5, 5.5);
        } else {
          const tx = g.x + 0.42;
          const vxTarget = 1.45;
          axDes = clamp(5.5 * (tx - p.x) + 3.5 * (vxTarget - v.x), -3.5, 4.8);

          const kpz = 15.0;
          const kdz = 7.2;
          azDes = clamp(kpz * (g.z - p.z) - kdz * v.z, -5.5, 5.5);

          const kpy = 13.0;
          const kdy = 6.2;
          ayDes = clamp(kpy * (g.y - p.y) - kdy * v.y, -4.5, 5.5);
        }
      } else {
        const pad = obs.pad.centre;
        const dPad = Math.hypot(pad.x - p.x, pad.z - p.z);
        const hSpeed = Math.hypot(v.x, v.z);
        const speed3D = Math.hypot(v.x, v.y, v.z);

        if (padPhase !== 'pin' && dPad < 0.115 && p.y <= 0.092 && speed3D < 0.42) {
          padPhase = 'pin';
        }
        if (padPhase === 'pin' && (dPad > 0.14 || p.y > 0.11)) {
          padPhase = 'descend';
        }

        if (padPhase === 'pin') {
          pinPad = true;
          maxTilt = 0.12;
          axDes = clamp(6.0 * (pad.x - p.x) - 4.0 * v.x, -1.5, 1.5);
          azDes = clamp(6.0 * (pad.z - p.z) - 4.0 * v.z, -1.5, 1.5);
          ayDes = -6.0;
        } else {
          let ty;
          if (dPad > 0.12 || hSpeed > 0.32) {
            ty = clamp(0.18 + 0.85 * dPad, 0.18, 0.95);
          } else {
            padPhase = 'descend';
            ty = 0.05;
          }

          const kpx = dPad < 0.25 ? 9.5 : 6.5;
          const kdx = gustMag > 1.5 ? 6.2 : 5.2;
          axDes = clamp(kpx * (pad.x - p.x) - kdx * v.x, -4.8, 4.8);
          azDes = clamp(kpx * (pad.z - p.z) - kdx * v.z, -4.8, 4.8);

          if (ty <= 0.10) {
            const vyTarget = p.y < 0.16 ? -0.18 : -0.35;
            ayDes = clamp(5.5 * (vyTarget - v.y), -3.0, 4.0);
            if (p.y < 0.18) maxTilt = 0.16;
          } else {
            ayDes = clamp(10.0 * (ty - p.y) - 5.5 * v.y, -3.5, 5.0);
          }
        }
      }

      const Tx = axDes + dragCoeff * v.x - (pinPad ? 0.3 * windAccX : windAccX);
      const Ty = clamp(9.81 + ayDes + dragCoeff * v.y, 2.5, 22.0);
      const Tz = azDes + dragCoeff * v.z - (pinPad ? 0.3 * windAccZ : windAccZ);

      const Tfwd = cy * Tx - sy * Tz;
      const Tlat = sy * Tx + cy * Tz;

      const pitchDes = clamp(Math.atan2(Tfwd, Ty), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(Tlat, Math.hypot(Tfwd, Ty)), -maxTilt, maxTilt);

      let thrustCmd;
      if (pinPad) {
        thrustCmd = 0.11;
      } else {
        const Sdes = Math.hypot(Tfwd, Ty, Tlat);
        thrustCmd = clamp(Sdes / thrustScale, 0.05, 1.0);
      }

      const rollRateDes = clamp((rollDes - prevRollDes) / dt, -3.0, 3.0);
      const pitchRateDes = clamp((pitchDes - prevPitchDes) / dt, -3.0, 3.0);
      prevRollDes = rollDes;
      prevPitchDes = pitchDes;

      const kpAtt = 75;
      const kdAtt = 14.5;

      const alphaRollDes = kpAtt * (rollDes - att.roll) + 0.35 * kdAtt * rollRateDes - kdAtt * rates.roll;
      const alphaPitchDes = kpAtt * (pitchDes - att.pitch) + 0.35 * kdAtt * pitchRateDes - kdAtt * rates.pitch;

      const rollCmd = clamp(
        att.roll + (alphaRollDes + 13.4 * rates.roll - 22 * simInt.roll - torqueBias.roll * thrustCmd) / 65,
        -0.6,
        0.6
      );
      const pitchCmd = clamp(
        att.pitch + (alphaPitchDes + 13.4 * rates.pitch - 22 * simInt.pitch - torqueBias.pitch * thrustCmd) / 65,
        -0.6,
        0.6
      );

      const yawRateDes = -2.8 * att.yaw - 0.35 * rates.yaw;
      const yawRateCmd = clamp(yawRateDes - (torqueBias.yaw * thrustCmd) / 8, -2.0, 2.0);

      lastAction = { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
      return lastAction;
    },
  };
}

