          const vxTarget = 1.25;
          axDes = clamp(5.0 * (tx - p.x) + 3.8 * (vxTarget - v.x), -4.0, 3.8);

          const kpz = 18.5;
          const kdz = 8.0;
          azDes = clamp(kpz * dz - kdz * v.z + 5.0 * intZ, -5.8, 5.8);

          const kpy = 15.0;
          const kdy = 6.6;
          ayDes = clamp(kpy * dy - kdy * v.y + 3.5 * intY, -4.5, 5.2);
        }
