            }
          }
        }
      }

      if (p.x > 2.35 && v.x > 0.3) {
        axDes = Math.min(axDes, -6.0 * v.x - 2.0);
      }

      const Tx = axDes + dragCoeff * v.x - (pinPad ? 0.25 * windAccX : windAccX);
      const Ty = clamp(9.81 + ayDes + dragCoeff * v.y, 2.5, 16.5);
      const Tz = azDes + dragCoeff * v.z - (pinPad ? 0.25 * windAccZ : windAccZ);

