      prevPitchDes = pitchDes;

      const kpAtt = 105;
      const kdAtt = 16.0;

      const alphaRollDes = kpAtt * (rollDes - att.roll) + 0.3 * kdAtt * rollRateDes - kdAtt * rates.roll;
      const alphaPitchDes = kpAtt * (pitchDes - att.pitch) + 0.3 * kdAtt * pitchRateDes - kdAtt * rates.pitch;

